def comps_of(g):
    H,W=len(g),len(g[0]); seen=set(); out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=0 and (r,c) not in seen:
                q=[(r,c)]; seen.add((r,c)); comp=[]
                while q:
                    y,x=q.pop(); comp.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        n=(y+dy,x+dx)
                        if 0<=n[0]<H and 0<=n[1]<W and g[n[0]][n[1]]!=0 and n not in seen:
                            seen.add(n); q.append(n)
                # center: unique-colored cell (or bbox center)
                cnt=Counter(g[y][x] for y,x in comp)
                center=min(cnt.items(), key=lambda kv:(kv[1] if True else 0))[0]
                # better: the cell whose color appears exactly once IF exists, else bbox center
                uniq=[p for p in comp if cnt[g[p[0]][p[1]]]==1]
                center=uniq[0] if len(uniq)==1 else comp[len(comp)//2]
                out.append((center,g[center[0]][center[1]],sorted(set(comp))))
    return out

def try_rule(g, order='arbitrary', protect=True):
    out=[r[:] for r in g]
    crosses=comps_of(g)
    # process orders
    if order=='row':
        pk=lambda x:x[0][0]
    elif order=='col':
        pk=lambda x:x[0][1]
    else:
        pk=lambda x:x[0]
    sorted_c=sorted(crosses,key=pk)
    for cr,col,cells in sorted_c:
        rr,cc=cr
        for c2 in range(len(out[0])):
            if protect and (rr,c2) in cells: continue
            if out[rr][c2]==0: out[rr][c2]=col
        for r2 in range(len(out)):
            if protect and (r2,cc) in cells: continue
            if out[r2][cc]==0: out[r2][cc]=col
    return out

