                cr=min(cand,key=lambda p:(p[0]-cy)**2+(p[1]-cx)**2) if cand else min(comp,key=lambda p:(p[0]-cy)**2+(p[1]-cx)**2)
                col=g[cr[0]][cr[1]]
                for c2 in range(W):
                    if out[cr[0]][c2]==0: out[cr[0]][c2]=col
                for r2 in range(H):
                    if out[r2][cr[1]]==0: out[r2][cr[1]]=col
    return out
